from __future__ import annotations


def _lesson(day, title, summary, terms, code, practice):
    concepts = "; ".join(f"{term} — {definition}" for term, definition in terms)
    return {
        "day": day,
        "title": title,
        "summary": summary,
        "terms": tuple(terms),
        "lecture": (
            f"В этом уроке разбираем тему «{title}». Главная цель: {summary.lower()}",
            f"Ключевые понятия урока: {concepts}. Не заучивайте их отдельно — находите каждое понятие в примере кода.",
            "Go ценит простой и явный код. Сначала определите входные данные, затем ожидаемый результат, после чего запишите минимальную последовательность действий.",
            f"После просмотра повторите пример вручную, измените одно значение и выполните практику: {practice}",
        ),
        "code": code.strip(),
        "practice": practice,
        "video_file": f"videos/go-course/lesson-{day:02d}.mp4",
    }


